"use client";

import type { SVGProps } from "react";
import { Select as SelectPrimitive } from "@base-ui/react/select";

import { cn } from "@/lib/utils";
import {
  formFieldBase,
  formFieldSingleLine,
  menuItemBase,
  popoverSurface,
  popupMotion,
} from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Firefly Select root: one choice from a short list. */
const Select = SelectPrimitive.Root;

/** Groups related options, and gives a label something to name. */
const SelectGroup = SelectPrimitive.Group;

/** Shows the chosen option inside the trigger, or the placeholder. */
const SelectValue = SelectPrimitive.Value;

/**
 * Firefly select trigger: the same warm paper well as every text field, with
 * a 0.75rem corner and a muted chevron at the end. The edge turns olive
 * while the list is open.
 */
function SelectTrigger({
  className,
  children,
  ...props
}: WithClassName<SelectPrimitive.Trigger.Props>) {
  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      className={cn(
        formFieldBase,
        formFieldSingleLine,
        "cursor-default items-center justify-between gap-2 whitespace-nowrap text-start",
        "data-[placeholder]:text-muted-foreground data-[popup-open]:border-(--accent-line)",
        "[&>span]:line-clamp-1",
        className,
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon className="flex shrink-0 text-muted-foreground">
        <ChevronDownIcon className="size-4" aria-hidden="true" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
}
SelectTrigger.displayName = "SelectTrigger";

/**
 * Firefly select list: the raised white menu panel with a 1rem corner and a
 * soft far shadow, at least as wide as its trigger. It grows from the trigger
 * and fades in over 200ms.
 */
function SelectContent({
  className,
  children,
  side,
  sideOffset = 6,
  align = "start",
  alignOffset,
  alignItemWithTrigger = false,
  ...props
}: WithClassName<SelectPrimitive.Popup.Props> &
  Pick<
    SelectPrimitive.Positioner.Props,
    "side" | "sideOffset" | "align" | "alignOffset" | "alignItemWithTrigger"
  >) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner
        className="isolate z-50 outline-none"
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        alignItemWithTrigger={alignItemWithTrigger}
      >
        <SelectPrimitive.Popup
          data-slot="select-content"
          className={cn(
            popoverSurface,
            popupMotion,
            "relative min-w-(--anchor-width) overflow-hidden",
            className,
          )}
          {...props}
        >
          <SelectPrimitive.ScrollUpArrow className="absolute inset-x-0 top-0 z-10 flex h-6 cursor-default items-center justify-center rounded-t-xl bg-popover text-muted-foreground">
            <ChevronUpIcon className="size-4" aria-hidden="true" />
          </SelectPrimitive.ScrollUpArrow>
          <SelectPrimitive.List
            data-slot="select-list"
            className={cn(
              "p-1",
              !alignItemWithTrigger &&
                "max-h-(--available-height) overflow-y-auto scroll-py-1",
            )}
          >
            {children}
          </SelectPrimitive.List>
          <SelectPrimitive.ScrollDownArrow className="absolute inset-x-0 bottom-0 z-10 flex h-6 cursor-default items-center justify-center rounded-b-xl bg-popover text-muted-foreground">
            <ChevronDownIcon className="size-4" aria-hidden="true" />
          </SelectPrimitive.ScrollDownArrow>
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  );
}
SelectContent.displayName = "SelectContent";

/** A small muted heading over a group of options. Use it inside a group. */
function SelectLabel({
  className,
  ...props
}: WithClassName<SelectPrimitive.GroupLabel.Props>) {
  return (
    <SelectPrimitive.GroupLabel
      data-slot="select-label"
      className={cn(
        "px-3 py-1.5 text-xs font-medium text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}
SelectLabel.displayName = "SelectLabel";

/**
 * An option row: 2.25rem tall with a 0.625rem corner that fills with the warm
 * surface when highlighted. The chosen option carries a near-black tick at
 * the end.
 */
function SelectItem({
  className,
  children,
  ...props
}: WithClassName<SelectPrimitive.Item.Props>) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      className={cn(menuItemBase, "w-full pe-8 data-[selected]:font-medium", className)}
      {...props}
    >
      <SelectPrimitive.ItemText className="line-clamp-1">
        {children}
      </SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator className="pointer-events-none absolute end-2 flex size-4 items-center justify-center">
        <CheckIcon className="size-4" aria-hidden="true" />
      </SelectPrimitive.ItemIndicator>
    </SelectPrimitive.Item>
  );
}
SelectItem.displayName = "SelectItem";

/** A hairline between option groups that runs to the panel's edges. */
function SelectSeparator({
  className,
  ...props
}: WithClassName<SelectPrimitive.Separator.Props>) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  );
}
SelectSeparator.displayName = "SelectSeparator";

export {
  Select,
  SelectGroup,
  SelectValue,
  SelectTrigger,
  SelectContent,
  SelectLabel,
  SelectItem,
  SelectSeparator,
};

// Carbon Icons, the icon library this system pairs with, drawn inline
// so the installed component loads no icon at runtime:
// "carbon:checkmark" "carbon:chevron-down" "carbon:chevron-up"
// One unit of stroke keeps the thin Carbon tick readable at small sizes.
// [BD-1029]
function CheckIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 32 32" aria-hidden="true" {...props}>
      <path fill="currentColor" stroke="currentColor" strokeWidth="1" strokeLinejoin="round" d="m13 24l-9-9l1.414-1.414L13 21.171L26.586 7.586L28 9z"/>
    </svg>
  );
}
function ChevronDownIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 32 32" aria-hidden="true" {...props}>
      <path fill="currentColor" d="M16 22L6 12l1.4-1.4l8.6 8.6l8.6-8.6L26 12z"/>
    </svg>
  );
}
function ChevronUpIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 32 32" aria-hidden="true" {...props}>
      <path fill="currentColor" d="m16 10l10 10l-1.4 1.4l-8.6-8.6l-8.6 8.6L6 20z"/>
    </svg>
  );
}
